// Package dump orchestrates pg_dump execution and streams its output to an
// HTTP client without buffering the archive in memory.
package dump

import (
	"fmt"
	"strings"
	"time"

	"github.com/fmotalleb/pg-dump-dashboard/internal/execution/pgclient"
)

// maxFilenameLen keeps attachments within filesystem limits after the
// timestamp and extension are appended.
const maxFilenameLen = 96

// Filename builds a safe attachment filename for a database dump.
//
// The database name is sanitised to an ASCII alphabet, the timestamp is always
// generated by the server and the extension depends on the dump format.
func Filename(database string, format pgclient.DumpFormat, now time.Time) string {
	base := SanitizeStem(database)
	return fmt.Sprintf("%s-%s%s", base, now.UTC().Format("20060102T150405Z"), extension(format))
}

func extension(format pgclient.DumpFormat) string {
	if format == pgclient.FormatPlain {
		return ".sql"
	}
	return ".dump"
}

// SanitizeStem reduces s to a conservative filename stem.
//
// Allowed characters are ASCII letters, digits, '-', '_' and '.'. Everything
// else becomes '_'. Path separators, control characters, quotes, leading dots
// and trailing dots or spaces can therefore never appear, which prevents
// header injection and path traversal regardless of how the value is used by
// the client.
func SanitizeStem(s string) string {
	var b strings.Builder
	b.Grow(len(s))

	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z',
			r >= 'A' && r <= 'Z',
			r >= '0' && r <= '9',
			r == '-', r == '_', r == '.':
			b.WriteRune(r)
		default:
			b.WriteByte('_')
		}
	}

	// Collapse traversal-like dot sequences; a stem is never a path, but this
	// keeps archives from looking suspicious in a downloads folder.
	out := strings.ReplaceAll(b.String(), "..", "_")
	out = strings.Trim(out, "._-")
	if len(out) > maxFilenameLen {
		out = strings.Trim(out[:maxFilenameLen], "._-")
	}
	if out == "" {
		out = "database"
	}
	return out
}

// ContentDisposition renders an RFC 6266 attachment header. The value is
// already reduced to a safe alphabet, so both the quoted form and the RFC 5987
// form are valid and cannot break out of the header.
func ContentDisposition(filename string) string {
	return fmt.Sprintf("attachment; filename=%q; filename*=utf-8''%s", filename, filename)
}

// ContentType returns the media type for a dump format.
func ContentType(format pgclient.DumpFormat) string {
	if format == pgclient.FormatPlain {
		// Plain SQL text. charset is explicit so browsers do not sniff.
		return "application/sql; charset=utf-8"
	}
	// pg_dump custom archives are binary.
	return "application/octet-stream"
}
